using System.Text.Json;
using System.Text.Json.Serialization.Metadata;

// Set up options with the default reflection-based resolver
var options = new JsonSerializerOptions
{
    TypeInfoResolver = new DefaultJsonTypeInfoResolver()
};

// 1) Strongly-typed retrieval: GetTypeInfo<T>() returns JsonTypeInfo<T> directly
JsonTypeInfo<Person> personInfo = (JsonTypeInfo<Person>)options.GetTypeInfo(typeof(Person));
Console.WriteLine($"Got JsonTypeInfo<Person> — Kind: {personInfo.Kind}, Type: {personInfo.Type.Name}");

// Serialize using the typed metadata
string json = JsonSerializer.Serialize(new Person("Alice", 30), personInfo);
Console.WriteLine($"Serialized: {json}");

// 2) Probe without throwing: TryGetTypeInfo returns false if metadata isn't available
//    Use a resolver that only knows about Person, so Widget will fail gracefully.
var limitedOptions = new JsonSerializerOptions
{
    TypeInfoResolver = new DefaultJsonTypeInfoResolver()
        .WithAddedModifier(ti =>
        {
            // Artificially block Widget by clearing its properties
            if (ti.Type == typeof(Widget))
                throw new NotSupportedException(); // resolver can't produce it
        })
};

// Person should succeed
if (limitedOptions.TryGetTypeInfo(typeof(Person), out JsonTypeInfo? foundInfo))
    Console.WriteLine($"\n✓ Metadata available for Person (Kind: {foundInfo!.Kind})");
else
    Console.WriteLine("\n✗ No metadata for Person");

// Widget should fail gracefully — no exception
if (limitedOptions.TryGetTypeInfo(typeof(Widget), out JsonTypeInfo? widgetInfo))
    Console.WriteLine($"✓ Metadata available for Widget (Kind: {widgetInfo!.Kind})");
else
    Console.WriteLine("✗ No metadata for Widget — handled without throwing");

// Records used in the demo
public record Person(string Name, int Age);
public record Widget(string Id, double Price);
