JsonTypeInfo<Person> personInfo = (JsonTypeInfo<Person>)options.GetTypeInfo(typeof(Person));
Console.WriteLine($"Got JsonTypeInfo<Person> — Kind: {personInfo.Kind}, Type: {personInfo.Type.Name}");

