string json = JsonSerializer.Serialize(new Person("Alice", 30), personInfo);
Console.WriteLine($"Serialized: {json}");

// 2) Probe without throwing: TryGetTypeInfo returns false when resolver
//    yields null for the requested type — no exception is thrown.
//    Use a custom resolver that only handles Person.
var limitedOptions = new JsonSerializerOptions
{
    TypeInfoResolver = JsonTypeInfoResolver.Combine(
        new PersonOnlyResolver())
};

// Person should succeed
if (limitedOptions.TryGetTypeInfo(typeof(Person), out JsonTypeInfo? foundInfo))
    Console.WriteLine($"\n✓ Metadata available for Person (Kind: {foundInfo!.Kind})");
